Here is the commit message:
dpaa2-switch: prevent ZERO_SIZE_PTR dereference when num_ifs
 is zero

The driver allocates arrays for ports, FDBs, and filter blocks using
kcalloc() with ethsw->sw_attr.num_ifs as the element count. When the
device reports zero interfaces (either due to hardware configuration
or firmware issues), kcalloc(0, ...) returns ZERO_SIZE_PTR (0x10)
instead of NULL.

Later in dpaa2_switch_probe(), the NAPI initialization unconditionally
accesses ethsw->ports[0]->netdev, which attempts to dereference
ZERO_SIZE_PTR (address 0x10), resulting in a kernel panic.

Add a check to ensure num_ifs is greater than zero after retrieving
device attributes. This prevents the zero-sized allocations and
subsequent invalid pointer dereference.

Reported-by: Yuhao Jiang <danisjiang@gmail.com>
Reported-by: Junrui Luo <moonafterrain@outlook.com>
Fixes: 0b1b71370458 ("staging: dpaa2-switch: handle Rx path on control interface")
Signed-off-by: Junrui Luo <moonafterrain@outlook.com>
Reviewed-by: Andrew Lunn <andrew@lunn.ch>
Link: https://patch.msgid.link/SYBPR01MB7881BEABA8DA896947962470AF91A@SYBPR01MB7881.ausprd01.prod.outlook.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The driver allocates arrays for ports, FDBs, and filter blocks using `kcalloc()` with `ethsw->sw_attr.num_ifs` as the element count without checking if `num_ifs` is zero. When the device reports zero interfaces, `kcalloc(0, ...)` returns `ZERO_SIZE_PTR` (address 0x10) instead of NULL. Subsequently, `dpaa2_switch_probe()` unconditionally accesses `ethsw->ports[0]->netdev`, which dereferences this invalid pointer, resulting in a kernel panic. The root cause is the missing validation of `num_ifs` after retrieving device attributes to prevent zero-sized allocations and subsequent invalid dereference.

Here is the patch:

 static int dpaa2_switch_init(struct fsl_mc_device *sw_dev)
 {
 	struct device *dev = &sw_dev->dev;
 	struct ethsw_core *ethsw = dev_get_drvdata(dev);
 	struct dpsw_vlan_if_cfg vcfg = {0};
 	struct dpsw_tci_cfg tci_cfg = {0};
 	struct dpsw_stp_cfg stp_cfg;
 	int err;
 	u16 i;

 	ethsw->dev_id = sw_dev->obj_desc.id;

 	err = dpsw_open(ethsw->mc_io, 0, ethsw->dev_id, &ethsw->dpsw_handle);
 	if (err) {
 		dev_err(dev, "dpsw_open err %d\n", err);
 		return err;
 	}

 	err = dpsw_get_attributes(ethsw->mc_io, 0, ethsw->dpsw_handle,
 				  &ethsw->sw_attr);
 	if (err) {
 		dev_err(dev, "dpsw_get_attributes err %d\n", err);
 		goto err_close;
 	}

+	if (!ethsw->sw_attr.num_ifs) {
+		dev_err(dev, "DPSW device has no interfaces\n");
+		err = -ENODEV;
+		goto err_close;
+	}
+
 	err = dpsw_get_api_version(ethsw->mc_io, 0,
 				   &ethsw->major,
 				   &ethsw->minor);
 	if (err) {
 		dev_err(dev, "dpsw_get_api_version err %d\n", err);
 		goto err_close;
 	}

 	/* Minimum supported DPSW version check */
 	if (ethsw->major < DPSW_MIN_VER_MAJOR ||
 	    (ethsw->major == DPSW_MIN_VER_MAJOR &&
 	     ethsw->minor < DPSW_MIN_VER_MINOR)) {
 		dev_err(dev, "DPSW version %d:%d not supported. Use firmware 10.28.0 or greater.\n",
 			ethsw->major, ethsw->minor);
 		err = -EOPNOTSUPP;
 		goto err_close;
 	}

 	if (!dpaa2_switch_supports_cpu_traffic(ethsw)) {
 		err = -EOPNOTSUPP;
 		goto err_close;
 	}

 	dpaa2_switch_detect_features(ethsw);

 	err = dpsw_reset(ethsw->mc_io, 0, ethsw->dpsw_handle);
 	if (err) {
 		dev_err(dev, "dpsw_reset err %d\n", err);
 		goto err_close;
 	}

 	stp_cfg.vlan_id = DEFAULT_VLAN_ID;
 	stp_cfg.state = DPSW_STP_STATE_FORWARDING;

 	for (i = 0; i < ethsw->sw_attr.num_ifs; i++) {
 		err = dpsw_if_disable(ethsw->mc_io, 0, ethsw->dpsw_handle, i);
 		if (err) {
 			dev_err(dev, "dpsw_if_disable err %d\n", err);
 			goto err_close;
 		}

 		err = dpsw_if_set_stp(ethsw->mc_io, 0, ethsw->dpsw_handle, i,
 				      &stp_cfg);
 		if (err) {
 			dev_err(dev, "dpsw_if_set_stp err %d for port %d\n",
 				err, i);
 			goto err_close;
 		}

 		/* Switch starts with all ports configured to VLAN 1. Need to
 		 * remove this setting to allow configuration at bridge join
 		 */
 		vcfg.num_ifs = 1;
 		vcfg.if_id[0] = i;
 		err = dpsw_vlan_remove_if_untagged(ethsw->mc_io, 0, ethsw->dpsw_handle,
 						   DEFAULT_VLAN_ID, &vcfg);
 		if (err) {
 			dev_err(dev, "dpsw_vlan_remove_if_untagged err %d\n",
 				err);
 			goto err_close;
 		}

 		tci_cfg.vlan_id = 4095;
 		err = dpsw_if_set_tci(ethsw->mc_io, 0, ethsw->dpsw_handle, i, &tci_cfg);
 		if (err) {
 			dev_err(dev, "dpsw_if_set_tci err %d\n", err);
 			goto err_close;
 		}

 		err = dpsw_vlan_remove_if(ethsw->mc_io, 0, ethsw->dpsw_handle,
 					  DEFAULT_VLAN_ID, &vcfg);
 		if (err) {
 			dev_err(dev, "dpsw_vlan_remove_if err %d\n", err);
 			goto err_close;
 		}
 	}

 	err = dpsw_vlan_remove(ethsw->mc_io, 0, ethsw->dpsw_handle, DEFAULT_VLAN_ID);
 	if (err) {
 		dev_err(dev, "dpsw_vlan_remove err %d\n", err);
 		goto err_close;
 	}

 	ethsw->workqueue = alloc_ordered_workqueue("%s_%d_ordered",
 						   WQ_MEM_RECLAIM, "ethsw",
 						   ethsw->sw_attr.id);
 	if (!ethsw->workqueue) {
 		err = -ENOMEM;
 		goto err_close;
 	}

 	err = dpsw_fdb_remove(ethsw->mc_io, 0, ethsw->dpsw_handle, 0);
 	if (err)
 		goto err_destroy_ordered_workqueue;

 	err = dpaa2_switch_ctrl_if_setup(ethsw);
 	if (err)
 		goto err_destroy_ordered_workqueue;

 	return 0;

 err_destroy_ordered_workqueue:
 	destroy_workqueue(ethsw->workqueue);

 err_close:
 	dpsw_close(ethsw->mc_io, 0, ethsw->dpsw_handle);
 	return err;
 }



